<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Exception\WebAuthnException;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnChallenge;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnCredential;

final class WebAuthnDomainUnitTest extends TestCase
{
    // --- WebAuthnException ---

    public function test_exception_challenge_expired(): void
    {
        $ex = WebAuthnException::challengeExpired();
        $this->assertStringContainsString('expired', $ex->getMessage());
        $this->assertInstanceOf(\RuntimeException::class, $ex);
    }

    public function test_exception_challenge_not_found(): void
    {
        $ex = WebAuthnException::challengeNotFound();
        $this->assertStringContainsString('not found', $ex->getMessage());
    }

    public function test_exception_credential_not_found(): void
    {
        $ex = WebAuthnException::credentialNotFound();
        $this->assertStringContainsString('not found', $ex->getMessage());
    }

    public function test_exception_credential_disabled(): void
    {
        $ex = WebAuthnException::credentialDisabled();
        $this->assertStringContainsString('disabled', $ex->getMessage());
    }

    public function test_exception_replay_attack(): void
    {
        $ex = WebAuthnException::replayAttack();
        $this->assertStringContainsString('replay', $ex->getMessage());
    }

    public function test_exception_verification_failed_includes_reason(): void
    {
        $ex = WebAuthnException::verificationFailed('origin mismatch');
        $this->assertStringContainsString('origin mismatch', $ex->getMessage());
    }

    // --- WebAuthnChallenge ---

    public function test_webauthn_challenge_stores_fields(): void
    {
        $now = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $expires = new DateTimeImmutable('2026-01-01T10:05:00+00:00');

        $challenge = new WebAuthnChallenge(
            challengeId: 'chal-1',
            tenantId: 'tenant',
            userUid: 'user-uid',
            challenge: 'base64-challenge',
            type: 'authentication',
            optionsJson: '{"timeout":60000}',
            createdAt: $now,
            expiresAt: $expires,
            verified: false,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        );

        $this->assertSame('chal-1', $challenge->challengeId);
        $this->assertSame('tenant', $challenge->tenantId);
        $this->assertSame('user-uid', $challenge->userUid);
        $this->assertSame('base64-challenge', $challenge->challenge);
        $this->assertSame('authentication', $challenge->type);
        $this->assertFalse($challenge->verified);
        $this->assertNull($challenge->verifiedAt);
    }

    public function test_webauthn_challenge_is_expired_when_past(): void
    {
        $challenge = $this->makeChallenge(expiresAt: new DateTimeImmutable('-1 second'));
        $this->assertTrue($challenge->isExpired());
    }

    public function test_webauthn_challenge_is_not_expired_when_future(): void
    {
        $challenge = $this->makeChallenge(expiresAt: new DateTimeImmutable('+60 seconds'));
        $this->assertFalse($challenge->isExpired());
    }

    public function test_webauthn_challenge_mark_verified_returns_new_instance(): void
    {
        $challenge = $this->makeChallenge();
        $this->assertFalse($challenge->verified);

        $verified = $challenge->markVerified('user-uid', 'alice@example.com');

        $this->assertTrue($verified->verified);
        $this->assertSame('user-uid', $verified->verifiedUserUid);
        $this->assertSame('alice@example.com', $verified->verifiedUsername);
        $this->assertNotNull($verified->verifiedAt);
        $this->assertFalse($challenge->verified, 'Original must be unmodified');
    }

    // --- WebAuthnCredential ---

    public function test_webauthn_credential_stores_fields(): void
    {
        $now = new DateTimeImmutable('2026-01-01T10:00:00+00:00');

        $cred = new WebAuthnCredential(
            uid: 'cred-uid',
            tenantId: 'tenant',
            userUid: 'user-uid',
            username: 'alice',
            credentialId: 'cred-id-base64',
            publicKey: 'pubkey-cbor',
            signCount: 5,
            aaguid: 'aaguid-value',
            deviceName: 'iPhone',
            transports: ['internal'],
            createdAt: $now,
            lastUsedAt: null,
            enabled: true,
        );

        $this->assertSame('cred-uid', $cred->uid);
        $this->assertSame('tenant', $cred->tenantId);
        $this->assertSame('user-uid', $cred->userUid);
        $this->assertSame('alice', $cred->username);
        $this->assertSame(5, $cred->signCount);
        $this->assertSame(['internal'], $cred->transports);
        $this->assertTrue($cred->enabled);
        $this->assertNull($cred->lastUsedAt);
    }

    public function test_webauthn_credential_with_updated_sign_count_returns_new_instance(): void
    {
        $now = new DateTimeImmutable();
        $cred = $this->makeCredential(signCount: 5);

        $updated = $cred->withUpdatedSignCount(6, $now);

        $this->assertSame(6, $updated->signCount);
        $this->assertSame($now, $updated->lastUsedAt);
        $this->assertSame(5, $cred->signCount, 'Original must be unmodified');
    }

    // --- helpers ---

    private function makeChallenge(?DateTimeImmutable $expiresAt = null): WebAuthnChallenge
    {
        $expiresAt ??= new DateTimeImmutable('+5 minutes');
        return new WebAuthnChallenge(
            challengeId: 'chal-1',
            tenantId: 'tenant',
            userUid: null,
            challenge: 'challenge-bytes',
            type: 'authentication',
            optionsJson: null,
            createdAt: new DateTimeImmutable(),
            expiresAt: $expiresAt,
            verified: false,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        );
    }

    private function makeCredential(int $signCount = 0): WebAuthnCredential
    {
        return new WebAuthnCredential(
            uid: 'cred-uid',
            tenantId: 'tenant',
            userUid: 'user-uid',
            username: 'alice',
            credentialId: 'cred-id',
            publicKey: 'pubkey',
            signCount: $signCount,
            aaguid: null,
            deviceName: null,
            transports: null,
            createdAt: new DateTimeImmutable(),
            lastUsedAt: null,
            enabled: true,
        );
    }
}
